/*
 * prog56_kruskal_mst.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program implements Kruskal's algorithm for a
 * fixed graph of 6 vertices (0 … 5) and at most 9 edges.  It reads the
 * number of edges from the command line, then reads that many edges from
 * standard input (each line:  a b w).  After building the Minimum Spanning
 * Tree it prints the total weight and the list of edges that belong to the
 * MST, or reports that the graph is disconnected.
 *
 * The original binary used an obfuscated state‑machine; the logic has been
 * recovered and expressed in clear C.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 6          /* vertices are 0 … 5 */
#define MAX_EDGES    9          /* hard‑coded limit in the original binary */

/* Union‑Find data structure */
static int parent[MAX_VERTICES];

static int find_set(int v)
{
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);   /* path compression */
    return parent[v];
}

static void union_set(int a, int b)
{
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra != rb)
        parent[ra] = rb;
}

/* Edge storage */
static int edge_a[MAX_EDGES];
static int edge_b[MAX_EDGES];
static int edge_w[MAX_EDGES];

/* Helper: simple selection sort of edge indices by weight */
static void sort_edge_indices(int idx[], int n)
{
    for (int i = 0; i < n - 1; ++i) {
        int best = i;
        for (int j = i + 1; j < n; ++j) {
            if (edge_w[idx[j]] < edge_w[idx[best]])
                best = j;
        }
        if (best != i) {
            int tmp = idx[i];
            idx[i] = idx[best];
            idx[best] = tmp;
        }
    }
}

int main(int argc, char **argv)
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long n_edges = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_edges < 0) {
        puts("INVALID_ARGS");
        return 0;
    }

    /* the original program caps the number of edges at 9 */
    if (n_edges > MAX_EDGES)
        n_edges = MAX_EDGES;

    /* ---------- initialise Union‑Find ---------- */
    for (int i = 0; i < MAX_VERTICES; ++i)
        parent[i] = i;

    /* ---------- read edges ---------- */
    for (int i = 0; i < n_edges; ++i) {
        if (scanf("%d %d %d", &edge_a[i], &edge_b[i], &edge_w[i]) != 3) {
            puts("INVALID_ARGS");
            return 0;
        }
        /* the original binary does not validate the vertex numbers;
         * we keep the same behaviour (out‑of‑range vertices will simply
         * never be united). */
    }

    /* ---------- Kruskal's algorithm ---------- */
    int idx[MAX_EDGES];
    for (int i = 0; i < n_edges; ++i)
        idx[i] = i;                     /* permutation of edge indices */

    sort_edge_indices(idx, n_edges);    /* sort by weight */

    int mst_weight = 0;
    int mst_edges   = 0;
    int mst_a[MAX_VERTICES - 1];
    int mst_b[MAX_VERTICES - 1];

    for (int i = 0; i < n_edges; ++i) {
        int e = idx[i];
        int a = edge_a[e];
        int b = edge_b[e];
        int w = edge_w[e];

        if (a < 0 || a >= MAX_VERTICES || b < 0 || b >= MAX_VERTICES)
            continue;                  /* ignore illegal vertices – same as the
                                          original program's behaviour */

        if (find_set(a) != find_set(b)) {
            union_set(a, b);
            mst_weight += w;
            mst_a[mst_edges] = a;
            mst_b[mst_edges] = b;
            ++mst_edges;
        }
    }

    /* ---------- output ---------- */
    if (mst_edges != MAX_VERTICES - 1) {
        puts("DISCONNECTED");
    } else {
        printf("weight=%d edges=", mst_weight);
        for (int i = 0; i < mst_edges; ++i) {
            printf("%d-%d", mst_a[i], mst_b[i]);
        }
        putchar('\n');
    }

    return 0;
}
